-- Hunter database. Jobs are public to read; each person can only see and change their own profile and tracking.
create table if not exists public.jobs (
  id text primary key,
  data jsonb not null,
  active boolean not null default true,
  found_on date not null default current_date,
  created_at timestamptz not null default now()
);
create table if not exists public.profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  data jsonb not null,
  updated_at timestamptz not null default now()
);
create table if not exists public.user_jobs (
  user_id uuid not null references auth.users(id) on delete cascade,
  job_id text not null references public.jobs(id) on delete cascade,
  status text not null default '' check (status in ('', 'saved', 'applied', 'interview', 'skipped')),
  notes text not null default '' check (char_length(notes) <= 4000),
  updated_at timestamptz not null default now(),
  primary key (user_id, job_id)
);
alter table public.jobs enable row level security;
alter table public.profiles enable row level security;
alter table public.user_jobs enable row level security;

drop policy if exists jobs_read on public.jobs;
create policy jobs_read on public.jobs for select to anon, authenticated using (active);

drop policy if exists profiles_own on public.profiles;
create policy profiles_own on public.profiles for all to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

drop policy if exists user_jobs_own on public.user_jobs;
create policy user_jobs_own on public.user_jobs for all to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

grant select on public.jobs to anon, authenticated;
grant select, insert, update, delete on public.profiles, public.user_jobs to authenticated;

