insert into public.jobs (id, data, active, found_on) values ('rimon', $j${"company": "אינטרנט רימון", "role": "מנהל תיקי לקוחות, מכירות שטח ופיתוח עסקי", "location": "גבעת שמואל, היברידי, שטח בפריסה ארצית", "url": "https://www.drushim.co.il/job/38887360/ed3bfd38/", "applyHow": "מגישים בכפתור \"הגשה\" בעמוד המשרה באתר דרושים. במודעה אין כתובת מייל.", "sells": "ספקית אינטרנט שמוכרת בעיקר בזכות אינטרנט מסונן לבתים, ויש לה גם קו מוצרים לעסקים. נפוצה בקרב משפחות ומוסדות דתיים.", "about": "הבעלות וגודל החברה לא אומתו. כדאי לברר לפני ראיון מהו בדיוק המוצר העסקי (סינון, קישוריות, אבטחה).", "requires": ["ניסיון משמעותי במכירות B2B ובניהול תיקי לקוחות עסקיים", "גיוס לקוחות חדשים מוכח", "ניהול עסקאות מורכבות עד סגירה", "יתרון: ניסיון בתקשורת", "נכונות לעבודת שטח ארצית. במודעה: 3 עד 4 שנות ניסיון"], "comp": "במודעה: \"שכר בסיס ועמלות\", רכב צמוד, טלפון ומחשב נייד. סכומים לא צוינו.", "regions": ["ארצי"], "mode": "היברידי", "car": "yes", "minYears": 3, "level": "mid", "sector": "תקשורת", "ask": ["מהו המוצר העסקי שהתפקיד מוכר?", "כמה מהזמן הוא ניהול תיק קיים וכמה גיוס לקוחות חדשים?", "מה מבנה העמלות?"]}$j$::jsonb, true, '2026-11-23')
