insert into public.jobs (id, data, active, found_on) values ('verifone', $j${"company": "Verifone", "role": "Sales Account Manager for Strategic Customers", "location": "תל אביב, היברידי", "url": "https://job-boards.greenhouse.io/verifone/jobs/7820464003", "applyHow": "מגישים בטופס שבעמוד המשרה (Greenhouse), עם קורות החיים באנגלית. במודעה אין כתובת מייל. הטופס שואל על ציפיות שכר ועל ראיון באנגלית.", "sells": "יצרנית עולמית של מסופי תשלום ותוכנת תשלומים. בישראל מוכרת לקמעונאים פתרונות קופה ותשלום, מנקודת המכירה ועד מטה הרשת.", "about": "חברה פרטית בבעלות קרן Francisco Partners (מידע כללי, כדאי לאמת לפני ראיון).", "requires": ["3 שנים ומעלה במכירות B2B או ניהול לקוחות אסטרטגיים, רצוי בתשלומים, פינטק או טכנולוגיה לקמעונאות", "הבנה של עולם הקמעונאות (קופות, סליקה)", "עבודה מול הנהלות בכירות ומחזורי מכירה ארוכים", "עברית שוטפת ושליטה ב-CRM (למשל Salesforce)", "יתרון: מכירה לרשתות ואנגלית שוטפת"], "comp": "לא צוינו שכר או רכב.", "regions": ["מרכז"], "mode": "היברידי", "car": "unknown", "minYears": 3, "level": "senior", "sector": "פיננסים ותשלומים", "english": "good", "ask": ["אילו רשתות נמצאות בתיק הלקוחות של התפקיד?", "מה אורך מחזור מכירה טיפוסי?", "מה מדיניות העבודה מהבית?"]}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
insert into public.jobs (id, data, active, found_on) values ('wolt', $j${"company": "Wolt", "role": "Media Sales SMB", "location": "רמת גן", "url": "https://job-boards.greenhouse.io/wolt/jobs/8171321", "applyHow": "מגישים בטופס שבעמוד המשרה (Greenhouse), עם קורות החיים באנגלית. במודעה אין כתובת מייל. המודעה פורסמה כבר בספטמבר 2026, כך שייתכן שהתהליך מתקדם.", "sells": "פלטפורמת משלוחים למסעדות ולקמעונאים, בבעלות DoorDash מאז 2022. התפקיד מוכר לבתי עסק קטנים ובינוניים חבילות פרסום וקידום בתוך האפליקציה.", "about": "חברה בינלאומית עם פעילות גדולה בישראל. יש שם משרה פתוחה נוספת מול רשתות מזון, שמוגדרת כהחלפה לחופשת לידה.", "requires": ["3 שנים ומעלה במכירות, רצוי מדיה, מסחר מקוון או טרייד מרקטינג", "ניסיון מוכח במכירה מלאה לעסקים קטנים ובינוניים", "חשיבה מסחרית ואנליטית ושימוש בנתונים", "כלי CRM (Salesforce, HubSpot, Monday)", "עברית ואנגלית מצוינות"], "comp": "לא צוינו שכר או רכב.", "regions": ["מרכז"], "mode": "משרד", "car": "unknown", "minYears": 3, "level": "mid", "sector": "קמעונאות", "english": "good", "ask": ["האם העבודה היא מהמשרד, או שיש גם פגישות אצל בתי העסק?", "מה היעדים החודשיים?", "באילו כלי נתונים ו-CRM עובדים?"]}$j$::jsonb, true, '2026-11-23')
  on conflict (id) do update set data = excluded.data, active = excluded.active;
